1	// Animated inline text swap: when the label changes, the old text fades/slides
2	// out and the new one slides in (e.g. "Change" → "Saving…" → "Saved",
3	// "Copy" → "Copied!"). Respects reduced motion. Zero layout opinion — the
4	// parent keeps its own sizing, so reserve space for the widest state there if
5	// shifts matter.
6	import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
7	import type { ReactNode } from "react";
8	
9	interface SwapTextProps {
10	  children: ReactNode;
11	  /** Identifies the current state; the swap animates when it changes.
12	      Defaults to the children themselves when they are a string/number. */
13	  swapKey?: string | number;
14	  /** Vertical travel in px of the outgoing/incoming text. */
15	  distance?: number;
16	  duration?: number;
17	}
18	
19	const SwapText = ({ children, swapKey, distance = 5, duration = 0.18 }: SwapTextProps) => {
20	  const reduce = useReducedMotion();
21	  const key =
22	    swapKey ??
23	    (typeof children === "string" || typeof children === "number" ? String(children) : "static");
24	
25	  return (
26	    <AnimatePresence mode="wait" initial={false}>
27	      <motion.span
28	        key={key}
29	        initial={{ opacity: 0, y: reduce ? 0 : distance }}
30	        animate={{ opacity: 1, y: 0 }}
31	        exit={{ opacity: 0, y: reduce ? 0 : -distance }}
32	        transition={{ duration, ease: "easeOut" }}
33	        style={{ display: "inline-block" }}
34	      >
35	        {children}
36	      </motion.span>
37	    </AnimatePresence>
38	  );
39	};
40	
41	export default SwapText;
